import json
import itertools

def find_itinerary():
    # Input variables
    total_days = 16
    cities = ["Bucharest", "Lyon", "Porto"]
    desired_stays = {"Bucharest": 7, "Lyon": 7, "Porto": 4}
    direct_flights_list = [("Bucharest", "Lyon"), ("Lyon", "Porto")]  # undirected
    wedding_city = "Bucharest"
    wedding_window = (1, 7)  # inclusive

    # Build undirected adjacency set
    direct_edges = set(frozenset(edge) for edge in direct_flights_list)

    # Helper to check if consecutive cities in the route have direct flights
    def route_is_direct(order):
        return all(frozenset({order[i], order[i+1]}) in direct_edges for i in range(len(order)-1))

    # We plan exactly 3 city blocks -> 2 flights
    number_of_flights = 2

    # Search for a feasible itinerary that satisfies all constraints
    for order in itertools.permutations(cities, 3):
        if not route_is_direct(order):
            continue

        # Validate total desired stay sum equals total_days + flights (double-count on flight days)
        if sum(desired_stays[c] for c in order) != total_days + number_of_flights:
            continue

        A, B, C = order
        a_end = desired_stays[A]
        b_end_from_AB = a_end + desired_stays[B] - 1
        b_end_from_C = total_days + 1 - desired_stays[C]

        # b_end must be consistent from both calculations
        if b_end_from_AB != b_end_from_C:
            continue
        b_end = b_end_from_AB

        # Validate range bounds
        if not (1 <= a_end <= b_end <= total_days):
            continue

        # Build segments (inclusive ranges). Flight days are overlaps.
        segments = [
            {"place": A, "start": 1, "end": a_end},
            {"place": B, "start": a_end, "end": b_end},
            {"place": C, "start": b_end, "end": total_days},
        ]

        # Wedding constraint: be in wedding_city at least one day within wedding_window
        w_start, w_end = wedding_window
        wedding_ok = False
        for seg in segments:
            if seg["place"] == wedding_city:
                if not (seg["end"] < w_start or seg["start"] > w_end):
                    wedding_ok = True
                    break
        if not wedding_ok:
            continue

        # Final verification that each city matches desired stay (including overlaps)
        valid_counts = True
        for seg in segments:
            days_in_city = seg["end"] - seg["start"] + 1
            if days_in_city != desired_stays[seg["place"]]:
                valid_counts = False
                break
        if not valid_counts:
            continue

        # If all constraints pass, format the itinerary
        itinerary = []
        for seg in segments:
            itinerary.append({
                "day_range": f"Day {seg['start']}-{seg['end']}",
                "place": seg["place"]
            })
        return {"itinerary": itinerary}

    # If no itinerary found, return empty itinerary
    return {"itinerary": []}

if __name__ == "__main__":
    result = find_itinerary()
    print(json.dumps(result))
